// ============================================================================================
//  THREE ISLANDS (user, 2026-07-29: "not all different islands they are 3 seperate islands 1-20,
//  20-40, 40-50. make the 20-40 island and the 40-50 island 5x larger")
// --------------------------------------------------------------------------------------------
//  A  Lv1-20   the starter, 4 provinces, BAKED and unchanged
//  B  Lv20-40  7 provinces, all one walkable mass, reached across the bridge
//  C  Lv40-50  4 provinces, reachable ONLY BY FLYING -- there is no land route and the audit
//              proves it with a flood fill rather than by measuring a gap
//
//  5x AREA IS sqrt(5) IN RADIUS. The old main island was r=343; five times its area is r=767, and
//  two of those plus the starter and the flight gap is what sets the world at 3700x1700. That is
//  6.29M tiles -- 6.29 MB in R.cells, one allocation, which is the whole reason Stage 6 packed the
//  grid before this landed. The old array-of-arrays-of-chars would have been ~500 MB of pointers.
//
//  IT IS A LOT OF WALKING and that is a deliberate consequence, not an oversight: island B is
//  1534 tiles across, about five minutes of holding one direction. Scale is a dial (ISLE_R), the
//  measurements are in _worldaudit.js, and Stage 11 adds the waypoints that make it navigable.
const WG_W = 3700, WG_H = 1700;

// Island A is re-centred vertically: its baked slice is 720 tall and the world is now 1700, so it
// would otherwise sit in the top-left corner with the bridge running diagonally down to nothing.
const ISLE_A_DY = 490;

// sqrt(5) * 343, rounded. One constant for both large islands, because "5x larger" was said once
// about both and two numbers that mean the same thing drift.
const ISLE_R = 767;

// The three islands, in id order -- and the id is what gets written into bits 5-6 of every tile
// byte by 02_worldbuild, so this order is load-bearing.
//   arrX/arrY  where you ARRIVE on it: the bridge mouth for B, the flight landing for C. Province
//              levels ramp with distance from this point, so it is what makes the world walk in
//              the right direction.
const WG_ISLES = [
  { id: 0, baked: true, arrX: 34, arrY: 283 + ISLE_A_DY },
  { id: 1, cx: 1237, cy: 850, r: ISLE_R, arrX: 470,  arrY: 850 },
  { id: 2, cx: 2891, cy: 850, r: ISLE_R, arrX: 2124, arrY: 850 }
];
// B's west coast is at 1237-767 = 470, which is where the bridge lands. C's west coast is at
// 2891-767 = 2124, and B's east coast is at 2004 -- so the water gap is 120 tiles.
// FLY_GAP_MIN IS A PROXY AND THE AUDIT DOES NOT TRUST IT. The real proof that C is flight-only is a
// flood fill from the starter landing that reaches zero cells on C. The number is here because it is
// the thing to TUNE if the fill ever fails: the widest player displacement is dash(200) = 4.5 tiles,
// solid()-gated and los()-swept, and the flight water exemption is gated on _pmove, which a dash
// does not set. 120 is twenty-six times that.
const FLY_GAP_MIN = 90;
// THE CHANNEL, AND WHY IT IS ENFORCED RATHER THAN HOPED FOR.
//
// Two islands 1654 tiles apart with a nominal radius of 767 look comfortably separate, and are not:
// the coastline noise reaches r*1.3, so each coast can push out to 997 and their maxima overlap by
// 340 tiles. The audit found 157 places where island B's land shared an edge with island C's -- and
// worse, the failure was nearly invisible, because the island ID is assigned by NEAREST CENTRE while
// the LAND is assigned by whichever field claimed the tile first. So a peninsula of C that reached
// west past the bisector was labelled island B: 4,060 tiles of Lv40-50 ground answering island B's
// province seeds, on the one island a player can only reach by flying to it. The reachability fill
// still passed, because that peninsula is physically part of C and nothing walks to it.
//
// A tile is land for its island only if it is CHANNEL tiles closer to that island's centre than to
// any other. That cuts a guaranteed strip of open water down the middle, wide enough that geometry
// and connectivity cannot disagree about which island a tile belongs to.
const CHANNEL = 130;

// ---- the province table, which is the whole level model ------------------------------------
// FIFTEEN PROVINCES, IN CLUMP ORDER, and this array is the single source for all of it: names,
// levels, themes and which island each one is on. ZBOSS and ZONE_TIERS are indexed by the same
// order (03_entities.js / 11_ui.js), which is why it is emitted as data on the room rather than
// duplicated there.
//
// A LABEL CAN NO LONGER DISAGREE WITH A LEVEL. The world this replaces had exactly that bug -- its
// ZONE_TIERS said Lv20-26 / 26-32 / 32-39 while the clumps measured about 35 / 43 / 45+ -- because
// levels came off a radial curve and the labels were typed separately. Here the province OWNS its
// range and grvLvAtR reads it back out, so the two cannot drift.
//
// band is the ART theme (ground atlas, minimap ramp, tree and boulder choice). Several provinces
// share one: B's first two are both band 3 green belt, C's last three are all band 8 burnt rim.
const WG_ZONES = [
  // island A -- unchanged, 4 provinces of 5 levels each
  { n: 'The Landing Sands', lv:  1, lv2:  5, band: 0, isle: 0 },
  { n: 'Gullwind Shore',    lv:  6, lv2: 10, band: 1, isle: 0 },
  { n: 'The Cairnworks',    lv: 11, lv2: 15, band: 9, isle: 0 },
  { n: 'Sawgrass Flats',    lv: 16, lv2: 20, band: 2, isle: 0 },
  // island B -- Lv20-40 across 7 provinces, walkable end to end
  { n: 'The Verdant Belt',  lv: 20, lv2: 22, band: 3, isle: 1 },
  { n: 'Wolfwood',          lv: 23, lv2: 25, band: 3, isle: 1 },
  { n: 'Deep Timber',       lv: 26, lv2: 28, band: 4, isle: 1 },
  { n: 'Stonebrow Rise',    lv: 29, lv2: 31, band: 5, isle: 1 },
  { n: 'Cinderwatch',       lv: 32, lv2: 34, band: 6, isle: 1 },
  { n: 'The Ashfall',       lv: 35, lv2: 37, band: 7, isle: 1 },
  { n: 'Charred Steppe',    lv: 38, lv2: 40, band: 7, isle: 1 },
  // island C -- Lv40-50, flight only. The Skyreach Shelf is where flight sets you down and is one
  // of the two provinces with NO BOSS: its waypoint has to stay clear so fast travel is always the
  // way out, because landing and aggroing something makes mountAllowedHere() false.
  { n: 'The Skyreach Shelf', lv: 40, lv2: 43, band: 7, isle: 2 },
  { n: 'The Glowing Waste',  lv: 44, lv2: 46, band: 8, isle: 2 },
  { n: 'Emberflow',          lv: 47, lv2: 49, band: 8, isle: 2 },
  // The Molten Heart is the other bossless one, and always was: ZBOSS[11] was already -1 on the old
  // world, so it carried a map label, a level range and its own loot row with nothing in it.
  { n: 'The Molten Heart',   lv: 50, lv2: 50, band: 8, isle: 2 }
];

// Province seeds, in clump order. HARD-CODED INTEGERS, not computed from angles: these feed
// _zoneAtRaw, which is a per-tile decision, and this file's determinism rule forbids trig anywhere
// a tile can see. They were laid out so that distance from each island's arrival point increases
// monotonically with level -- which is what makes "walk away from where you landed" mean "walk into
// harder ground", and what the audit's border check depends on.
const WG_SEEDS = [
  [ 90,  780], [168,  815], [228,  882], [292,  928],                       // A, +ISLE_A_DY applied
  [679,  871], [795,  618], [947, 1143], [1234, 695], [1338, 1237],
  [1490, 319], [1793, 983],                                                 // B, west -> east
  [2324, 850], [2567, 578], [2743, 1292], [3236, 716]                       // C, west -> east
];

const WG_RINGS = {
  radial: true,
  // starter/bridge keep their old meaning; core/main/rmax/grindR are RETIRED by the province-owned
  // level model and kept only until Stage 11 finishes deleting their last readers.
  starter: { cx: 34, cy: 283 + ISLE_A_DY, r: 330 },
  bridge:  { x0: 352, x1: 470, cy: 850, w: 10 },
  core:    { cx: 470, cy: 850 },
  main:    { cx: 1237, cy: 850, r: ISLE_R },
  rmax: 1300,
  grindR: 0.8,
  portal:  { x: 3560, y: 850 },
  isles: WG_ISLES,
  zones: WG_ZONES,
  seeds: WG_SEEDS,
  // BAND-INDEXED, ten entries, bands 0..9. Four callers still index this by band and one of them
  // (genDungeon's rings.names[ring]) conflates a boss id with a band -- Stage 11's job. The ranges
  // are DERIVED from WG_ZONES below rather than typed, so a label cannot disagree with a level.
  names: [],
  grind: ['The Ashfall', 'Charred Steppe', 'The Molten Heart', 'The Glowing Waste', 'Emberflow'],
  starterZones: [
    { n: 'The Landing Sands', lv: 1,  lv2: 5  },
    { n: 'Gullwind Shore',    lv: 6,  lv2: 10 },
    { n: 'The Cairnworks',    lv: 11, lv2: 15 },
    { n: 'Sawgrass Flats',    lv: 16, lv2: 20 }
  ]
};
// names[band] = the first province using that band, widened to cover every province that uses it.
(function () {
  const by = {};
  for (const z of WG_ZONES) {
    const b = z.band;
    if (!by[b]) by[b] = { n: z.n, lv: z.lv, lv2: z.lv2 };
    else { by[b].lv = Math.min(by[b].lv, z.lv); by[b].lv2 = Math.max(by[b].lv2, z.lv2); }
  }
  for (let b = 0; b <= 9; b++) WG_RINGS.names[b] = by[b] || { n: 'Unmapped', lv: 1, lv2: 1 };
})();

// One waypoint per province, at its seed, so a 3700-tile world is navigable at all. Stage 11 adds
// more. `b` is the BAND, which is what openFastTravel reads for the level label.
//
// NUDGED ONTO STANDABLE GROUND, at build time. A seed is a Voronoi centre, which is a point chosen
// for how it partitions the island and not for what happens to be on it -- the audit found Sawgrass
// Flats' waypoint sitting inside a boulder, on the BAKED island where the generator does not stamp.
// A pillar you cannot stand on is a fast-travel destination that drops you inside terrain.
const WG_PILLARS = WG_ZONES.map((z, i) => ({ b: z.band, name: z.n, tx: WG_SEEDS[i][0], ty: WG_SEEDS[i][1] }));

// ---- coastlines -----------------------------------------------------------------------------
// A radial field with a domain-warped, fBm-perturbed threshold. The shape of the curve is measured
// off the world this replaces:
//
//   radius / R      land fraction in the artifact
//     up to 0.70     1.00
//     0.70-0.82      0.96
//     0.82-0.93      0.79
//     0.93-1.05      0.57      <- the 50% crossing, which is what R means
//     1.05-1.17      0.35
//     1.17-1.28      0.13
//     1.28-1.40      0.01
//
// so `1 - r/R + noise` thresholded at 0, with noise amplitude ~0.30, reproduces it: at r/R = 1.17
// it needs noise > 0.17 of a ~±0.30 range, which is about an eighth of the time.
//
// The frequencies SCALE WITH THE ISLAND. They were tuned at r=343; used unchanged on an island
// 2.24x larger they would produce the same size of bay on a much bigger coast, which reads as a
// smooth circle with nibbles out of it rather than as a coastline.
const ISLE_AMP  = 0.30;         // how far the coast wanders, as a fraction of the island radius
const ISLE_FREQ = 1 / 46;       // coastline detail at r=343; scaled by r/343 below
const WARP_AMP  = 26;           // tiles of domain warp at r=343; likewise scaled
const WARP_FREQ = 1 / 120;
const REF_R = 343;

function wgLandAt(isle, tx, ty) {
  const k = isle.r / REF_R;                     // everything spatial scales with the island
  const wf = WARP_FREQ / k, cf = ISLE_FREQ / k;
  const wx = tx + (wgVal(tx * wf, ty * wf, WORLD_SEED + 101 + isle.id) * 2 - 1) * WARP_AMP * k;
  const wy = ty + (wgVal(tx * wf, ty * wf, WORLD_SEED + 202 + isle.id) * 2 - 1) * WARP_AMP * k;
  const dx = wx - isle.cx, dy = wy - isle.cy;
  const r = Math.sqrt(dx * dx + dy * dy);
  const n = (wgFbm(tx * cf, ty * cf, WORLD_SEED + 303 + isle.id, 4) * 2 - 1) * ISLE_AMP;
  return (1 - r / isle.r + n) > 0;
}

// Does this island own the tile outright? Only if it is CHANNEL tiles closer to this island's
// centre than to any other one -- which leaves a strip of guaranteed water between every pair.
function wgOwns(isle, tx, ty) {
  const dx = tx - isle.cx, dy = ty - isle.cy;
  const d = Math.sqrt(dx * dx + dy * dy);
  for (const O of WG_ISLES) {
    if (O.id === isle.id || O.baked || O.cx == null) continue;
    const ox = tx - O.cx, oy = ty - O.cy;
    if (d + CHANNEL > Math.sqrt(ox * ox + oy * oy)) return false;
  }
  return true;
}

// ---- ground ---------------------------------------------------------------------------------
// PER 2x2 BLOCK, NOT PER TILE, and that is measured: the artifact's horizontal runs of one
// character are overwhelmingly EVEN in length (27,139 runs of 2, 8,171 of 4, 3,089 of 6, and 122
// of 1) with a mean of 3.1. Its generator worked on a 2x2 grid and drew each block independently,
// so the ground is dithered at 2-tile granularity rather than laid out in coherent patches.
// Matching that is both simpler and more faithful than inventing regions the world never had.
//
// The mixes are the measured per-band histograms, cumulative so one random number picks one char.
//   r = scree and bare rock   d = dirt / open ground   e = burnt ash flats   g = grassland
//   k = boulder (blocks a small circle)   c/s = spawn markers, consumed by 02_worldbuild's sweep
const WG_MIX = [
  [['d',0.310],['r',0.594],['g',0.866],['e',0.934],['k',0.979],['c',0.994],['s',1.000]],  // band 3
  [['r',0.411],['d',0.778],['g',0.859],['e',0.926],['k',0.983],['c',0.995],['s',1.000]],  // band 4
  [['r',0.404],['d',0.784],['e',0.856],['g',0.927],['k',0.983],['c',0.993],['s',1.000]],  // band 5
  [['r',0.425],['d',0.708],['e',0.886],['k',0.944],['g',0.984],['c',0.993],['s',1.000]],  // band 6
  [['r',0.360],['e',0.700],['d',0.911],['k',0.968],['g',0.983],['c',0.994],['s',1.000]],  // band 7
  [['e',0.446],['r',0.761],['d',0.927],['k',0.983],['c',0.993],['s',1.000]]               // band 8
];
function wgGroundFor(band, roll) {
  const row = WG_MIX[Math.max(0, Math.min(WG_MIX.length - 1, band - 3))];
  for (let i = 0; i < row.length; i++) if (roll < row[i][1]) return row[i][0];
  return row[row.length - 1][0];
}
// THE BAND FOR A TILE, WITHOUT THE PROVINCE TABLE. The generator runs before 03_entities.js, so it
// cannot call zoneAt -- and it does not need to: which province a tile belongs to only matters for
// the ATLAS at render time, while the ground CHARACTER is texture variety. Nearest seed on the same
// island, which is the same rule _zoneAtRaw uses minus the warp, is close enough and costs one pass.
function wgBandAt(isle, tx, ty) {
  let best = -1, bd = 1e18;
  for (let i = 0; i < WG_ZONES.length; i++) {
    if (WG_ZONES[i].isle !== isle.id) continue;
    const dx = tx - WG_SEEDS[i][0], dy = ty - WG_SEEDS[i][1], d = dx * dx + dy * dy;
    if (d < bd) { bd = d; best = i; }
  }
  return best < 0 ? 3 : Math.max(3, Math.min(8, WG_ZONES[best].band));
}

// ---- the generator --------------------------------------------------------------------------
function genWorld() {
  const W = WG_W, H = WG_H, R = WG_RINGS;
  const b = R.bridge, half = (b.w / 2) | 0;

  // island A's baked rows, dropped into the taller world at ISLE_A_DY
  const a = wgRleRows(ISLE_A_RLE, ISLE_A_W, 720);
  const rows = new Array(H);
  for (let y = 0; y < H; y++) {
    const row = new Array(W).fill('w');
    const src = a[y - ISLE_A_DY];
    if (src) for (let x = 0; x < ISLE_A_W; x++) row[x] = src[x];
    rows[y] = row;
  }

  // --- islands B and C ---
  for (const isle of WG_ISLES) {
    if (isle.baked) continue;
    const x0 = Math.max(0, Math.floor(isle.cx - isle.r * 1.45));
    const x1 = Math.min(W - 1, Math.ceil(isle.cx + isle.r * 1.45));
    const y0 = Math.max(0, Math.floor(isle.cy - isle.r * 1.45));
    const y1 = Math.min(H - 1, Math.ceil(isle.cy + isle.r * 1.45));
    for (let y = y0; y <= y1; y++) {
      const row = rows[y];
      for (let x = x0; x <= x1; x++) {
        if (row[x] !== 'w') continue;
        if (!wgOwns(isle, x, y)) continue;              // the channel: see CHANNEL above
        if (!wgLandAt(isle, x, y)) continue;
        const band = wgBandAt(isle, x, y);
        row[x] = wgGroundFor(band, wgRand(x >> 1, y >> 1, WORLD_SEED + 404 + band));
      }
    }
  }

  // --- the bridge, A to B ---
  for (let y = b.cy - half; y < b.cy - half + b.w; y++) {
    if (y < 0 || y >= H) continue;
    for (let x = b.x0; x <= b.x1; x++) rows[y][x] = 'b';
  }

  // --- guarantee the ground under everything that MUST exist ---
  // A noise field is entitled to put water under a waypoint or the rift, and a portal in the sea is
  // an unreachable endgame. Stamped after the coastline and before the connectivity fill, so the
  // fill can also reach them.
  const stamp = (tx, ty, rad, ch) => {
    for (let y = ty - rad; y <= ty + rad; y++) {
      if (y < 0 || y >= H) continue;
      for (let x = tx - rad; x <= tx + rad; x++) {
        if (x < ISLE_A_W || x >= W) continue;            // never touch island A
        const dx = x - tx, dy = y - ty;
        if (dx * dx + dy * dy > rad * rad) continue;
        if (rows[y][x] === 'b') continue;
        rows[y][x] = ch;
      }
    }
  };
  stamp(R.portal.x, R.portal.y, 12, 'd');
  for (let i = 0; i < WG_SEEDS.length; i++) {
    if (WG_ZONES[i].isle === 0) continue;
    stamp(WG_SEEDS[i][0], WG_SEEDS[i][1], 9, 'd');
  }

  // --- THE APPROACH ROAD, AND WHY IT IS NOT OPTIONAL ---
  // The bridge lands on island B's 50% coastline, where the field is a coin flip. The first run of
  // this generator (at the old size) drowned all 341,052 tiles of the eastern world for exactly that
  // reason: the fill crossed the causeway, filled a 177-tile apron, hit a wall of noise-water and
  // stopped, so everything beyond counted as an orphan. The picture would have been an empty ocean
  // with a pier in it. So the causeway gets a landfall that is guaranteed rather than hoped for: a
  // three-tile dirt SPINE from the bridge mouth inland, wandering on its own low-frequency noise so
  // it reads as an isthmus and not as a ruler line, with band ground filled in around it.
  const road = (fromX, toX, atY, isle) => {
    for (let x = fromX; x <= toX; x++) {
      // THE WOBBLE RAMPS IN FROM ZERO. It used to start at full amplitude, so the spine could begin
      // eleven tiles off the causeway's centre line -- and the causeway is ten tiles wide, so the
      // road started BESIDE the bridge instead of at the end of it, with open water between them.
      // It survived because the taper happened to fill the join often enough to keep the flood fill
      // connected, which is the worst kind of pass: the map showed a bridge ending in the sea.
      const ramp = Math.min(1, (x - fromX) / 60);
      const wob = Math.round((wgVal(x / 70, 0.5, WORLD_SEED + 505 + isle.id) * 2 - 1) * 11 * ramp);
      const y0 = atY + wob;
      // and the first stretch is as wide as the causeway itself, so the join is a landfall and not
      // a three-tile path meeting a ten-tile road
      const spine = (x - fromX < 24) ? half : 1;
      for (let dy = -9; dy <= 9; dy++) {
        const y = y0 + dy;
        if (y < 1 || y >= H - 1) continue;
        if (rows[y][x] === 'b') continue;
        if (Math.abs(dy) <= spine) { rows[y][x] = 'd'; continue; }
        if (rows[y][x] !== 'w') continue;
        if (wgRand(x, y, WORLD_SEED + 606) < (9 - Math.abs(dy)) / 9) {
          const band = wgBandAt(isle, x, y);
          rows[y][x] = wgGroundFor(band, wgRand(x >> 1, y >> 1, WORLD_SEED + 404 + band));
        }
      }
    }
  };
  road(b.x1, Math.round(WG_ISLES[1].cx - WG_ISLES[1].r * 0.55), b.cy, WG_ISLES[1]);

  // --- nudge every waypoint onto ground you can stand on ---
  // Spiral out from the seed for the nearest non-solid, non-water tile. Runs after the stamps (so a
  // generated island's pillar is already standing in a cleared disc) and before the fill (so the
  // pillar is part of the mass the fill measures).
  const SOLIDCH = 'WhlHwXD';
  for (const pl of WG_PILLARS) {
    const at = (x, y) => (rows[y] && rows[y][x]) || 'w';
    if (SOLIDCH.indexOf(at(pl.tx, pl.ty)) < 0) continue;
    let done = false;
    for (let rad = 1; rad < 60 && !done; rad++) {
      for (let dy = -rad; dy <= rad && !done; dy++) for (let dx = -rad; dx <= rad && !done; dx++) {
        if (Math.abs(dx) !== rad && Math.abs(dy) !== rad) continue;
        const x = pl.tx + dx, y = pl.ty + dy;
        if (x < 1 || y < 1 || x >= W - 1 || y >= H - 1) continue;
        if (SOLIDCH.indexOf(at(x, y)) >= 0) continue;
        pl.tx = x; pl.ty = y; done = true;
      }
    }
  }

  // --- CONNECTIVITY, PER ISLAND ---
  // An explicit Int32Array stack, never recursion: island B alone is over a million tiles and a
  // recursive fill would take the stack with it.
  //
  // SEEDED PER ISLAND, AND THAT IS THE FLIGHT GATE. B is filled from the bridge mouth, C from its
  // own arrival point -- there is no seed that can walk from one to the other, because there is 120
  // tiles of open water between them. Anything an island's own fill never touched is an orphan
  // islet and gets drowned; what is NOT done is joining them up.
  const seen = new Uint8Array(W * H);
  const stack = new Int32Array(W * H);
  const fillFrom = (sx, sy) => {
    let sp = 0, n = 0;
    const push = (x, y) => {
      if (x < 0 || y < 0 || x >= W || y >= H) return;
      const i = y * W + x;
      if (seen[i] || rows[y][x] === 'w') return;
      seen[i] = 1; stack[sp++] = i;
    };
    // the arrival point itself may be one tile off the coast; spiral out for a foothold
    for (let rad = 0; rad < 40 && sp === 0; rad++) {
      for (let dy = -rad; dy <= rad; dy++) for (let dx = -rad; dx <= rad; dx++) {
        if (Math.abs(dx) !== rad && Math.abs(dy) !== rad) continue;
        push(sx + dx, sy + dy);
      }
    }
    while (sp > 0) {
      const i = stack[--sp]; n++;
      const x = i % W, y = (i - x) / W;
      if (x + 1 < W  && !seen[i + 1] && rows[y][x + 1] !== 'w') { seen[i + 1] = 1; stack[sp++] = i + 1; }
      if (x - 1 >= 0 && !seen[i - 1] && rows[y][x - 1] !== 'w') { seen[i - 1] = 1; stack[sp++] = i - 1; }
      if (y + 1 < H  && !seen[i + W] && rows[y + 1][x] !== 'w') { seen[i + W] = 1; stack[sp++] = i + W; }
      if (y - 1 >= 0 && !seen[i - W] && rows[y - 1][x] !== 'w') { seen[i - W] = 1; stack[sp++] = i - W; }
    }
    return n;
  };
  const reach = [];
  reach.push(fillFrom(b.x1, b.cy));                                   // A and B, across the bridge
  reach.push(fillFrom(WG_ISLES[2].arrX + 6, WG_ISLES[2].arrY));       // C, on its own

  let drowned = 0;
  for (let y = 0; y < H; y++) {
    const row = rows[y];
    for (let x = ISLE_A_W; x < W; x++) {
      if (row[x] !== 'w' && !seen[y * W + x]) { row[x] = 'w'; drowned++; }
    }
  }

  const map = new Array(H);
  for (let y = 0; y < H; y++) map[y] = rows[y].join('');

  return {
    big: true, w: W, h: H, name: 'The Sundered Isles',
    // A FRESH COPY OF THE SPEC, not the module's own object. 02_worldbuild pushes onto rings.names
    // and _territories caches its table on rings, so handing out WG_RINGS itself means the second
    // call to genWorld() -- which is how the audit proves determinism -- gets a spec the first
    // call's world already modified.
    rings: JSON.parse(JSON.stringify(WG_RINGS)),
    pillars: JSON.parse(JSON.stringify(WG_PILLARS)),
    map: map,
    _gen: { reached: reach, drowned: drowned, seed: WORLD_SEED }
  };
}

// ---- the fingerprint ------------------------------------------------------------------------
// FNV-1a over the tile data plus a CANONICAL form of everything hand-authored. Two peers compare
// this at the handshake: a mismatch is a different world, and it is far better to refuse the join
// than to discover it as a desync when one player walks into a rock the other cannot see.
//
// NOT JSON.stringify(def.rings). The first version did exactly that and the audit caught it: the
// hash was not reproducible from the same world. `rings` is handed to 02_worldbuild, which pushes
// onto rings.names, and to _territories, which caches _terr on it -- so by the time anything
// re-checks, stringifying it includes a whole territory table that was not there at load. A
// fingerprint has to be built from named fields, so that what it covers is a decision.
function worldHash(def) {
  let h = 0x811c9dc5;
  const mix = (s) => {
    s = String(s);
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
  };
  for (const row of def.map) mix(row);
  mix(def.w + 'x' + def.h + '|' + WORLD_SEED);
  const R = def.rings;
  mix([R.starter.cx, R.starter.cy, R.starter.r,
       R.bridge.x0, R.bridge.x1, R.bridge.cy, R.bridge.w,
       R.portal.x, R.portal.y].join(','));
  for (const i of R.isles) mix([i.id, i.cx | 0, i.cy | 0, i.r | 0, i.arrX, i.arrY].join(','));
  for (const z of R.zones) mix(z.n + ':' + z.lv + '-' + z.lv2 + ':' + z.band + ':' + z.isle);
  for (const s of R.seeds) mix(s[0] + ',' + s[1]);
  for (const p of def.pillars) mix(p.b + ':' + p.name + ':' + p.tx + ',' + p.ty);
  return ('0000000' + h.toString(16)).slice(-8);
}

ROOM_DEFS['G'] = genWorld();
const WORLD_HASH = worldHash(ROOM_DEFS['G']);
